// Utilidades de line protocol de InfluxDB (se insertan al inicio de cada función de persistencia).
// Un tag vacío o con salto de línea invalida la línea y InfluxDB rechazaría el lote completo (400).
const escTag = (v) => String(v == null || v === '' ? 'unknown' : v).replace(/[\r\n]+/g, ' ').slice(0, 64).replace(/[,= ]/g, (c) => '\\' + c);
// Un salto de línea separa registros en line protocol: se sustituye por espacio (evita inyección de filas).
const escStr = (v) => '"' + String(v).replace(/[\r\n]+/g, ' ').replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const isDev = (id) => /^DEV(0[1-9]|1[0-2])$/.test(id);
const MAX_AGE_MS = 10 * 24 * 3600 * 1000; // IDEAM publica con retraso de hasta varios días
const MAX_FUTURE_MS = 5 * 60 * 1000;
function bump(key) {
    const s = flow.get('stats') || { ok: 0, rejected: 0 };
    s[key] = (s[key] || 0) + 1;
    flow.set('stats', s);
    node.status({ fill: s.rejected ? 'yellow' : 'green', shape: 'dot', text: 'ok ' + s.ok + ' · rechazados ' + s.rejected });
}

// Valida telemetría y la convierte en una línea `telemetry` (una fila ancha por mensaje).
const p = msg.payload;
const topicDev = msg.topic.split('/')[1];
const reject = (why) => { bump('rejected'); node.warn('Telemetría rechazada (' + topicDev + '): ' + why); return null; };
if (!p || typeof p !== 'object') return reject('no es JSON');
if (!isDev(p.device_id) || p.device_id !== topicDev) return reject('device_id no coincide con el tópico');
const ts = Date.parse(p.timestamp);
if (!Number.isFinite(ts)) return reject('timestamp inválido');
if (ts > Date.now() + MAX_FUTURE_MS || ts < Date.now() - MAX_AGE_MS) return reject('timestamp fuera de rango');
if (!p.variables || typeof p.variables !== 'object') return reject('sin variables');
const fields = [];
for (const [k, obj] of Object.entries(p.variables)) {
    if (!/^[a-z0-9_]{1,40}$/.test(k) || !obj) continue;
    const v = obj.value;
    // Los numéricos se guardan siempre como float para que la agregación los trate igual.
    if (typeof v === 'number' && Number.isFinite(v)) fields.push(k + '=' + (Number.isInteger(v) ? v + '.0' : v));
    else if (typeof v === 'string') fields.push(k + '=' + escStr(v.slice(0, 64)));
    else if (typeof v === 'boolean') fields.push(k + '=' + v);
}
if (fields.length === 0) return reject('sin variables válidas');
if (Number.isInteger(p.seq)) fields.push('seq=' + p.seq + 'i');
const synthetic = !!(p.provenance && p.provenance.synthetic === true);
const src = ['simulated', 'digital_twin', 'api', 'dataset', 'real'].includes(p.source_type) ? p.source_type : 'unknown';
bump('ok');
msg.payload = 'telemetry,device_id=' + escTag(p.device_id) + ',source_type=' + src + ',synthetic=' + synthetic + ' ' + fields.join(',') + ' ' + ts;
return msg;

// Utilidades de line protocol de InfluxDB (se insertan al inicio de cada función de persistencia).
// Un tag vacío o con salto de línea invalida la línea y InfluxDB rechazaría el lote completo (400).
const escTag = (v) => String(v == null || v === '' ? 'unknown' : v).replace(/[\r\n]+/g, ' ').slice(0, 64).replace(/[,= ]/g, (c) => '\\' + c);
// Un salto de línea separa registros en line protocol: se sustituye por espacio (evita inyección de filas).
const escStr = (v) => '"' + String(v).replace(/[\r\n]+/g, ' ').replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const isDev = (id) => /^DEV(0[1-9]|1[0-2])$/.test(id);
const MAX_AGE_MS = 10 * 24 * 3600 * 1000; // IDEAM publica con retraso de hasta varios días
const MAX_FUTURE_MS = 5 * 60 * 1000;
function bump(key) {
    const s = flow.get('stats') || { ok: 0, rejected: 0 };
    s[key] = (s[key] || 0) + 1;
    flow.set('stats', s);
    node.status({ fill: s.rejected ? 'yellow' : 'green', shape: 'dot', text: 'ok ' + s.ok + ' · rechazados ' + s.rejected });
}

// Historial de conexión (para disponibilidad). Se usa la hora de recepción: el LWT lleva la hora de conexión.
const p = msg.payload;
const topicDev = msg.topic.split('/')[1];
if (!p || !isDev(p.device_id) || p.device_id !== topicDev) { bump('rejected'); return null; }
const conn = p.connection === 'online' ? 'online' : 'offline';
const state = ['running', 'stopped', 'degraded', 'error'].includes(p.state) ? p.state : 'unknown';
const fields = ['online=' + (conn === 'online' ? '1.0' : '0.0')];
if (typeof p.reason === 'string') fields.push('reason=' + escStr(p.reason.slice(0, 200)));
bump('ok');
msg.payload = 'device_status,device_id=' + p.device_id + ',connection=' + conn + ',state=' + state + ' ' + fields.join(',') + ' ' + Date.now();
return msg;

// Utilidades de line protocol de InfluxDB (se insertan al inicio de cada función de persistencia).
// Un tag vacío o con salto de línea invalida la línea y InfluxDB rechazaría el lote completo (400).
const escTag = (v) => String(v == null || v === '' ? 'unknown' : v).replace(/[\r\n]+/g, ' ').slice(0, 64).replace(/[,= ]/g, (c) => '\\' + c);
// Un salto de línea separa registros en line protocol: se sustituye por espacio (evita inyección de filas).
const escStr = (v) => '"' + String(v).replace(/[\r\n]+/g, ' ').replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const isDev = (id) => /^DEV(0[1-9]|1[0-2])$/.test(id);
const MAX_AGE_MS = 10 * 24 * 3600 * 1000; // IDEAM publica con retraso de hasta varios días
const MAX_FUTURE_MS = 5 * 60 * 1000;
function bump(key) {
    const s = flow.get('stats') || { ok: 0, rejected: 0 };
    s[key] = (s[key] || 0) + 1;
    flow.set('stats', s);
    node.status({ fill: s.rejected ? 'yellow' : 'green', shape: 'dot', text: 'ok ' + s.ok + ' · rechazados ' + s.rejected });
}

// Eventos de incidentes SINTÉTICOS de DEV04. Solo se aceptan si vienen marcados como sintéticos.
const p = msg.payload;
const i = p && p.incident;
if (!i || p.device_id !== 'DEV04' || i.synthetic !== true || !/^SIM-INC-[A-Z0-9-]+$/.test(i.incident_id)) { bump('rejected'); return null; }
const ts = Date.parse(p.timestamp);
if (!Number.isFinite(ts)) { bump('rejected'); return null; }
// Un número no finito (NaN) haría que InfluxDB rechazara el lote entero: se descarta solo este evento.
const nums = [i.location && i.location.lat, i.location && i.location.lon, i.speed_impact, i.lanes_blocked].map(Number);
if (!nums.every(Number.isFinite)) { bump('rejected'); node.warn('Incidente descartado: coordenadas o métricas no numéricas'); return null; }
const tags = [
    'event=' + escTag(p.event), 'type=' + escTag(i.type), 'severity=' + escTag(i.severity),
    'state=' + escTag(i.state), 'road_class=' + escTag(i.road_class), 'test=' + (i.test === true), 'synthetic=true',
].join(',');
const fields = [
    'incident_id=' + escStr(i.incident_id), 'road_name=' + escStr(i.road_name), 'segment_id=' + escStr(i.segment_id),
    'lat=' + nums[0], 'lon=' + nums[1], 'speed_impact=' + nums[2], 'lanes_blocked=' + Math.trunc(nums[3]) + '.0',
].join(',');
bump('ok');
msg.payload = 'incident_events,' + tags + ' ' + fields + ' ' + ts;
return msg;

// Encola una línea validada en la cola persistente del flujo (contexto en disco, sobrevive a reinicios).
// Un temporizador la envía por lotes a InfluxDB. Tope de 20 000 líneas: si se supera se descartan las más antiguas.
const MAX_PENDING = 20000;
if (!msg.payload) return null;
const pending = flow.get('pending') || [];
pending.push(msg.payload);
if (pending.length > MAX_PENDING) pending.splice(0, pending.length - MAX_PENDING);
flow.set('pending', pending);
return null;

// Cada 2 s: toma hasta 5000 líneas de la cola persistente y arma la petición de escritura.
// Solo una petición en vuelo a la vez; si no hay respuesta en 30 s se considera perdida y se reintenta.
const BATCH = 5000;
const inflight = flow.get('inflight');
if (inflight && Date.now() - inflight.at < 30000) return null;
let pending = flow.get('pending') || [];
if (inflight) pending = inflight.lines.concat(pending); // la petición anterior no respondió: se reintenta
if (pending.length === 0) { flow.set('inflight', null); return null; }
const lines = pending.slice(0, BATCH);
flow.set('pending', pending.slice(BATCH));
flow.set('inflight', { at: Date.now(), lines: lines });
msg.lines = lines;
msg.url = env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG')) +
    '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET_RAW')) + '&precision=ms';
msg.method = 'POST';
msg.headers = { Authorization: 'Token ' + env.get('INFLUX_WRITE_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = lines.join('\n');
return msg;

// 204 = escrito. Ante error de red o 5xx las líneas vuelven al frente de la cola persistente (máx. 20 000).
// Un 4xx indica datos que InfluxDB nunca aceptará: se registran y se descartan para no bloquear la cola.
const MAX_PENDING = 20000;
flow.set('inflight', null);
const lines = msg.lines || [];
if (msg.statusCode === 204) {
    const total = (flow.get('written') || 0) + lines.length;
    flow.set('written', total);
    node.status({ fill: 'green', shape: 'dot', text: 'escritas ' + total + ' · pendientes ' + (flow.get('pending') || []).length });
    return null;
}
if (msg.statusCode >= 400 && msg.statusCode < 500) {
    node.error('InfluxDB rechazó el lote (' + msg.statusCode + '): ' + String(msg.payload).slice(0, 300));
    node.status({ fill: 'red', shape: 'ring', text: 'rechazado ' + msg.statusCode });
    return null;
}
const pending = lines.concat(flow.get('pending') || []);
flow.set('pending', pending.slice(-MAX_PENDING));
const why = msg.statusCode || (msg.error && (msg.error.code || msg.error.message)) || msg.error;
node.status({ fill: 'yellow', shape: 'ring', text: 'reintento · pendientes ' + pending.length });
node.warn('InfluxDB no disponible (' + why + '); ' + lines.length + ' líneas reencoladas');
return null;

// Construye una orden válida según el contrato MQTT (command_id UUID v4 + issued_at).
function uuid4() {
    const h = [];
    for (let i = 0; i < 32; i++) h.push(Math.floor(Math.random() * 16).toString(16));
    h[12] = '4';
    h[16] = (8 + Math.floor(Math.random() * 4)).toString(16);
    const s = h.join('');
    return s.slice(0, 8) + '-' + s.slice(8, 12) + '-' + s.slice(12, 16) + '-' + s.slice(16, 20) + '-' + s.slice(20);
}
function command(device, action, params, rule) {
    return {
        topic: 'smartcity/' + device + '/control',
        qos: 1,
        payload: { command_id: uuid4(), action: action, params: params, issued_at: new Date().toISOString(), issued_by: 'nodered:' + rule },
    };
}

// REGLA 1 — Restricción vehicular por calidad del aire.
// Si el AQI de DEV02 llega a 150 (dañino) se reduce la demanda de tráfico simulada en DEV05 (medida tipo
// "pico y placa ambiental"). Se restablece cuando el AQI baja de 100. Actúa solo en transiciones (histéresis).
const v = msg.payload && msg.payload.variables;
const aqi = v && v.us_aqi && v.us_aqi.value;
if (typeof aqi !== 'number') return null;
const active = flow.get('air_restriction') === true;
if (!active && aqi >= 150) {
    flow.set('air_restriction', true);
    node.status({ fill: 'red', shape: 'dot', text: 'restricción activa (AQI ' + aqi + ')' });
    return command('DEV05', 'set_params', { demand_factor: 0.7 }, 'restriccion_aire');
}
if (active && aqi < 100) {
    flow.set('air_restriction', false);
    node.status({ fill: 'green', shape: 'dot', text: 'normal (AQI ' + aqi + ')' });
    return command('DEV05', 'set_params', { demand_factor: 1 }, 'restriccion_aire');
}
node.status({ fill: active ? 'red' : 'green', shape: 'ring', text: 'AQI ' + aqi });
return null;

